60:     );
61:     this.construirForm(this.formAdicionales, 'aspirantes.titulo_adicionales');
62: 
63:     const campoTipoIdentificacion = this.formIdentificacion.campos.find(
64:       (c: any) => c.nombre === 'TipoIdentificacion',
65:     );
66:     if (campoTipoIdentificacion) {
67:       campoTipoIdentificacion.opciones = this.tiposDocumento;
68:     }
69: 
70:     this.info_persona_id = await this.userService.getPersonaId();
71:     await this.loadInfoPersona();
