74:   construirForm(form: any, tituloKey: string) {
75:     for (let i = 0; i < form.campos.length; i++) {
76:       form.campos[i].label = this.translate.instant(
77:         'aspirantes.' + form.campos[i].label_i18n,
78:       );
79:       form.campos[i].placeholder = this.translate.instant(
80:         'aspirantes.' + form.campos[i].placeholder_i18n,
81:       );
82:     }
83:     form.titulo = this.translate.instant(tituloKey);
84:     form.btn = '';
85:   }
