87:   getForm(grupo: Grupo): any {
88:     if (grupo === 'basicos') return this.formBasicos;
89:     if (grupo === 'identificacion') return this.formIdentificacion;
90:     return this.formAdicionales;
91:   }
92: 
93:   modificar(grupo: Grupo) {
94:     if (grupo === 'adicionales' && !this.puedeEditarAdicionales) {
95:       this.popUpManager.showAlert(
96:         '',
97:         this.translate.instant('aspirantes.no_telefono'),
98:       );
99:       return;
100:     }
101:     this.editing[grupo] = true;
102:     this.setEditing(grupo, true);
103:   }
104: 
105:   guardar(grupo: Grupo) {
106:     const form = this.getForm(grupo);
107:     const data: any = {};
108:     form.campos.forEach((c: any) => (data[c.nombre] = c.valor));
109:     console.log(`Guardar cambios [${grupo}]:`, data);
110:     this.editing[grupo] = false;
111:     this.setEditing(grupo, false);
112:     if (grupo == 'basicos') {
113:       this.actualizarBasicos(data);
114:     } else if (grupo == 'identificacion') {
115:       this.actualizarIdentificacion(data);
116:     } else if (grupo == 'adicionales') {
117:       this.actualizarAdicionales(data);
118:     } else {
119:       console.log("No se ha seleccionado un grupo correcto para actualizar");
120:     }
121:   }
122: 
123:   async actualizarBasicos (data) {
124:     if (this.info_persona_id === null || this.info_persona_id === undefined) {
125:       this.loading = false;
126:       this.popUpManager.showAlert(
127:         '',
128:         this.translate.instant('aspirantes.no_persona'),
129:       );
130:       return;
131:     }
132: 
133:     this.tercerosService.get('tercero/' + this.info_persona_id).subscribe({
134:       next: (res: any) => {
135:         
136:         let basic_data = res;
137:         basic_data.PrimerNombre = data.PrimerNombre;
138:         basic_data.SegundoNombre = data.SegundoNombre;
139:         basic_data.PrimerApellido = data.PrimerApellido;
140:         basic_data.SegundoApellido = data.SegundoApellido;
141:         basic_data.FechaNacimiento = data.FechaNacimiento;
142: 
143:         console.log(basic_data);
144:         this.tercerosService.put('tercero/', basic_data).subscribe({
145:           next: (response: any) => {
146:             // console.log('Tercero actualizado:', response);
147:             this.popUpManager.showSuccessAlert(this.translate.instant('aspirantes.exito'));
148:           },
149:           error: (error: any) => {
150:             console.error('Error actualizando tercero:', error);
151:             this.popUpManager.showErrorToast(this.translate.instant('aspirantes.error'));
152:           }
153:         });
154:       },
155:       error: (error: any) => {
156:         console.error('Error consultando tercero:', error);
157:         this.popUpManager.showErrorToast(this.translate.instant('aspirantes.error'));
158:       }
159:     });
160:     
161:   }
162: 
163:   async actualizarIdentificacion (data) {
164:     if (this.info_persona_id === null || this.info_persona_id === undefined) {
165:       this.loading = false;
166:       this.popUpManager.showAlert(
167:         '',
168:         this.translate.instant('aspirantes.no_persona'),
169:       );
170:       return;
171:     }
172: 
173:     this.tercerosService.get('datos_identificacion?query=Activo:True,Numero:'+ data.NumeroIdentificacion +',TerceroId__Id:' + this.info_persona_id).subscribe({
174:       next: (res: any) => {
175:         let data_id = res[0];
176:         const nuevoTipoDocumento = {
177:           Id: data.TipoIdentificacion.Id
178:         }
179:         
180:         data_id.FechaExpedicion = data.FechaExpedicion;
181:         data_id.NumeroIdentificacion = data.NumeroIdentificacion;
182:         data_id.TipoDocumentoId = nuevoTipoDocumento;
183: 
184:         this.tercerosService.put('datos_identificacion/', data_id).subscribe({
185:             next: (response: any) => {
186:               console.log('Identificación actualizada:', response);
187:               this.popUpManager.showSuccessAlert(this.translate.instant('aspirantes.exito'));
188:             },
189:             error: (error: any) => {
190:               console.error('Error actualizando identificación:', error);
191:               this.popUpManager.showErrorToast(this.translate.instant('aspirantes.error'));
192:             }
193:         });
194:       },
195:       error: (error: any) => {
196:         console.error('Error consultando identificación:', error);
197:         this.popUpManager.showErrorToast(this.translate.instant('aspirantes.error'));
198:       }
199:     });
200:   }
