266:   public async loadInfoPersona() {
267:     if (this.info_persona_id === null || this.info_persona_id === undefined) {
268:       this.loading = false;
269:       this.popUpManager.showAlert(
270:         '',
271:         this.translate.instant('aspirantes.no_persona'),
272:       );
273:       return;
