276:     this.tercerosMidService.get('personas/' + this.info_persona_id).subscribe({
277:       next: (res: any) => {
278:         const d = res?.Data;
279:         if (!d) {
280:           this.loading = false;
281:           this.popUpManager.showAlert(
282:             '',
283:             this.translate.instant('aspirantes.no_data'),
