6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path: string;
19:   public httpOptions: any;
20:   constructor(private http: HttpClient, private errManager: HttpErrorManager) {
21:     const acces_token = window.localStorage.getItem('access_token');
22:     if (acces_token !== null) {
23:       this.httpOptions = {
24:         headers: new HttpHeaders({
25:           'Content-Type': 'application/json',
26:           'Authorization': `Bearer ${acces_token}`,
27:         }),
28:       }
29:     }
30:   }
31: 
32:   /**
33:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
34:    * @param service: string
35:    */
36:   public setPath(service: string) {
37:     this.path = environment[service];
38:   }
39: 
40: 
41:   /**
42:    * Perform a GET http request
43:    * @param endpoint service's end-point
44:    * @param params (an Key, Value object with que query params for the request)
45:    * @returns Observable<any>
46:    */
47:   get(endpoint: string) {
48: 
49:     return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
50:       map(
51:         (res) => {
52:           if (res.hasOwnProperty('Body')) {
53:             return res['Body'];
54:           } else {
55:             return res;
56:           }
57:         },
58:       ),
59:       catchError(this.errManager.handleError.bind(this)),
60:     );
61:   }
62: 
63:   /**
64:    * Perform a POST http request
65:    * @param endpoint service's end-point
66:    * @param element data to send as JSON
67:    * @returns Observable<any>
68:    */
69:   post(endpoint: string, element: any) {
70:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
71:       catchError(this.errManager.handleError),
72:     );
73:   }
74: 
75:   /**
76:    * Perform a POST http request
77:    * @param endpoint service's end-point
78:    * @param element data to send as JSON
79:    * @returns Observable<any>
80:    */
81:   post_file(endpoint: string, element: any) {
82:     return this.http.post<any>(`${this.path}${endpoint}`, element, {    headers: new HttpHeaders({
83:       'Content-Type': 'multipart/form-data',
84:   })}).pipe(
85:       catchError(this.errManager.handleError),
86:     );
87:   }
88: 
89:   /**
90:    * Perform a PUT http request
91:    * @param endpoint service's end-point
92:    * @param element data to send as JSON, With the id to UPDATE
93:    * @returns Observable<any>
94:    */
95:   put(endpoint: string, element: any) {
96:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
97:     return this.http.put<any>(path, element, this.httpOptions).pipe(
98:       catchError(this.errManager.handleError),
99:     );
100:   }
101: 
102:   /**
103:    * Perform a DELETE http request
104:    * @param endpoint service's end-point
105:    * @param id element's id for remove
106:    * @returns Observable<any>
107:    */
108:   delete(endpoint: string, id: any) {
109:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
110:       catchError(this.errManager.handleError),
111:     );
