73:   readVerifyMimeType(file: File): Promise<boolean> {
74:     return new Promise<boolean>((resolve) => {
75:       const reader = new FileReader();
76:       reader.onload = () => {
77:         const arrayBuffer = reader.result as ArrayBuffer;
78:         const uint8Array = new Uint8Array(arrayBuffer.slice(0, 8));
79:         const mime = Array.from(uint8Array)
80:           .map((byte) => byte.toString(16).padStart(2, '0'))
81:           .join('')
82:           .toUpperCase();
83:         const extension = file.type || 'none';
84:         resolve(
85:           this.fileSignatures[extension].some((sign) => mime.startsWith(sign))
86:         );
87:       };
88:       reader.onerror = () => resolve(false);
89:       reader.readAsArrayBuffer(file);
